package com.techprotech.agenda.modulos.productos.aplicacion;
import java.time.Clock;
import com.techprotech.agenda.compartido.tiempo.ZonaNegocio;
import com.techprotech.agenda.modulos.parametros.aplicacion.ServicioParametrosSistema; import com.techprotech.agenda.modulos.prestadores.infraestructura.entidad.PrestadorServicioEntidad; import com.techprotech.agenda.modulos.prestadores.infraestructura.repositorio.PrestadorServicioRepositorio; import com.techprotech.agenda.modulos.productos.api.dto.*; import com.techprotech.agenda.modulos.productos.infraestructura.entidad.*; import com.techprotech.agenda.modulos.productos.infraestructura.repositorio.*; import com.techprotech.agenda.modulos.servicios.infraestructura.entidad.ServicioEntidad; import com.techprotech.agenda.modulos.servicios.infraestructura.repositorio.ServicioRepositorio; import com.techprotech.agenda.modulos.sucursales.infraestructura.repositorio.SucursalRepositorio; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import org.springframework.web.server.ResponseStatusException; import java.time.LocalDate; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service public class ServicioComisiones{
 private final Clock reloj; private final ZonaNegocio zonasNegocio;
 private static final Set<String> CONCEPTOS=Set.of("SERVICIO","PRODUCTO","VENTA_TOTAL"),ALCANCES=Set.of("GLOBAL","ESPECIFICO","CATEGORIA"),BENEFICIARIOS=Set.of("PRESTADOR","VENDEDOR"),TIPOS=Set.of("PORCENTAJE","MONTO_FIJO"),BASES=Set.of("BRUTO","NETO_DESCUENTOS","MARGEN");
 private final ReglaComisionRepositorio reglas;private final ServicioRepositorio servicios;private final ProductoRepositorio productos;private final CategoriaProductoRepositorio categorias;private final PrestadorServicioRepositorio prestadores;private final SucursalRepositorio sucursales;private final ServicioParametrosSistema parametros;
 public ServicioComisiones(ReglaComisionRepositorio a,ServicioRepositorio b,ProductoRepositorio c,CategoriaProductoRepositorio d,PrestadorServicioRepositorio e,SucursalRepositorio f,ServicioParametrosSistema g, Clock reloj, ZonaNegocio zonasNegocio){this.reloj=reloj;this.zonasNegocio=zonasNegocio;reglas=a;servicios=b;productos=c;categorias=d;prestadores=e;sucursales=f;parametros=g;}
 @Transactional(readOnly=true) public CatalogoComisionesResponse catalogo(Long empresa){var ss=servicios.findByEmpresaIdOrderByNombreAsc(empresa);var ps=productos.findByEmpresaIdOrderByNombreAsc(empresa);var cs=categorias.findByEmpresaIdOrderByOrdenAscNombreAsc(empresa);var sedes=sucursales.findByEmpresaIdOrderByNombreAsc(empresa);var prs=prestadores.findBySucursalIdInOrderByNombreMostrarAsc(sedes.stream().map(x->x.getId()).toList());Map<Long,String> sm=mapa(ss,ServicioEntidad::getId,ServicioEntidad::getNombre),pm=mapa(ps,ProductoEntidad::getId,ProductoEntidad::getNombre),cm=mapa(cs,CategoriaProductoEntidad::getId,CategoriaProductoEntidad::getNombre),prm=mapa(prs,PrestadorServicioEntidad::getUsuarioId,PrestadorServicioEntidad::getNombreMostrar);return new CatalogoComisionesResponse(moneda(empresa),op(sm),op(pm),op(cm),op(prm),reglas.findByEmpresaIdOrderByPrioridadDescNombreAsc(empresa).stream().map(x->map(x,sm,pm,cm,prm)).toList(), Map.of("concepto",CONCEPTOS.stream().sorted().toList(),"alcance",ALCANCES.stream().sorted().toList(),"beneficiario",BENEFICIARIOS.stream().sorted().toList(),"tipoCalculo",TIPOS.stream().sorted().toList(),"baseCalculo",BASES.stream().sorted().toList()));}
 @Transactional public ReglaComisionResponse crear(Long empresa,ReglaComisionRequest r){var e=new ReglaComisionEntidad();e.setEmpresaId(empresa);aplicar(empresa,e,r);reglas.save(e);return buscar(empresa,e.getId());}
 @Transactional public ReglaComisionResponse actualizar(Long empresa,Long id,ReglaComisionRequest r){var e=reglas.findByIdAndEmpresaId(id,empresa).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Regla no encontrada"));aplicar(empresa,e,r);reglas.save(e);return buscar(empresa,id);}
 private void aplicar(Long empresa,ReglaComisionEntidad e,ReglaComisionRequest r){String concepto=c(r.concepto()),alcance=c(r.alcance()),benef=c(r.beneficiario()),tipo=c(r.tipoCalculo()),base=c(r.baseCalculo());if(!CONCEPTOS.contains(concepto)||!ALCANCES.contains(alcance)||!BENEFICIARIOS.contains(benef)||!TIPOS.contains(tipo)||!BASES.contains(base))throw error("La configuración de comisión no es válida");if("VENTA_TOTAL".equals(concepto)&&!"GLOBAL".equals(alcance))throw error("La venta total requiere alcance general");if("CATEGORIA".equals(alcance)&&!"PRODUCTO".equals(concepto))throw error("El alcance por categoría aplica sólo a productos");if("ESPECIFICO".equals(alcance)&&(("SERVICIO".equals(concepto)&&r.servicioId()==null)||("PRODUCTO".equals(concepto)&&r.productoId()==null)))throw error("Selecciona el elemento de la comisión");if("CATEGORIA".equals(alcance)&&r.categoriaProductoId()==null)throw error("Selecciona la categoría de la comisión");if(r.fechaInicio()!=null&&r.fechaFin()!=null&&r.fechaFin().isBefore(r.fechaInicio()))throw error("La fecha final debe ser posterior a la inicial");if("PORCENTAJE".equals(tipo)&&r.valor().doubleValue()>100)throw error("El porcentaje no puede superar 100");if(r.servicioId()!=null)servicios.findByIdAndEmpresaId(r.servicioId(),empresa).orElseThrow(()->error("Servicio no válido"));if(r.productoId()!=null)productos.findByIdAndEmpresaId(r.productoId(),empresa).orElseThrow(()->error("Producto no válido"));if(r.categoriaProductoId()!=null)categorias.findByIdAndEmpresaId(r.categoriaProductoId(),empresa).orElseThrow(()->error("Categoría no válida"));if(r.prestadorId()!=null&&!catalogo(empresa).prestadores().stream().anyMatch(x->x.id().equals(r.prestadorId())))throw error("Prestador no válido");e.setNombre(r.nombre().trim());e.setDescripcion(t(r.descripcion()));e.setConcepto(concepto);e.setAlcance(alcance);e.setServicioId("SERVICIO".equals(concepto)&&"ESPECIFICO".equals(alcance)?r.servicioId():null);e.setProductoId("PRODUCTO".equals(concepto)&&"ESPECIFICO".equals(alcance)?r.productoId():null);e.setCategoriaProductoId("PRODUCTO".equals(concepto)&&"CATEGORIA".equals(alcance)?r.categoriaProductoId():null);e.setBeneficiario(benef);e.setPrestadorId(r.prestadorId());e.setTipoCalculo(tipo);e.setBaseCalculo(base);e.setValor(r.valor());e.setMoneda("MONTO_FIJO".equals(tipo)?(StringUtils.hasText(r.moneda())?c(r.moneda()):moneda(empresa)):null);e.setFechaInicio(r.fechaInicio());e.setFechaFin(r.fechaFin());e.setPrioridad(r.prioridad());e.setActiva(r.activa());}
 private ReglaComisionResponse buscar(Long e,Long id){return catalogo(e).reglas().stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}private ReglaComisionResponse map(ReglaComisionEntidad e,Map<Long,String>s,Map<Long,String>p,Map<Long,String>c,Map<Long,String>pr){return new ReglaComisionResponse(e.getId(),e.getNombre(),e.getDescripcion(),e.getConcepto(),e.getAlcance(),e.getServicioId(),s.get(e.getServicioId()),e.getProductoId(),p.get(e.getProductoId()),e.getCategoriaProductoId(),c.get(e.getCategoriaProductoId()),e.getBeneficiario(),e.getPrestadorId(),pr.get(e.getPrestadorId()),e.getTipoCalculo(),e.getBaseCalculo(),e.getValor(),e.getMoneda(),e.getFechaInicio(),e.getFechaFin(),e.getPrioridad(),e.isActiva(),estado(e));}
 private String estado(ReglaComisionEntidad e){var h=LocalDate.now(reloj.withZone(zonasNegocio.de(e.getEmpresaId(), (Long) null)));if(!e.isActiva())return"INACTIVA";if(e.getFechaInicio()!=null&&h.isBefore(e.getFechaInicio()))return"PROGRAMADA";if(e.getFechaFin()!=null&&h.isAfter(e.getFechaFin()))return"EXPIRADA";return"VIGENTE";}private String moneda(Long e){return parametros.listar(e).stream().filter(x->"MONEDA_PREDETERMINADA".equals(x.clave())).map(x->x.valor()).findFirst().orElseThrow();}private <T>Map<Long,String>mapa(List<T>l,Function<T,Long>i,Function<T,String>n){return l.stream().collect(Collectors.toMap(i,n,(a,b)->a));}private List<CatalogoComisionesResponse.Opcion>op(Map<Long,String>m){return m.entrySet().stream().sorted(Map.Entry.comparingByValue()).map(x->new CatalogoComisionesResponse.Opcion(x.getKey(),x.getValue())).toList();}private String c(String x){return x.trim().toUpperCase(Locale.ROOT);}private String t(String x){return StringUtils.hasText(x)?x.trim():null;}private ResponseStatusException error(String x){return new ResponseStatusException(HttpStatus.BAD_REQUEST,x);}
}
